import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'

type Initial = {
  name?: string
  category?: string
  sku?: string
  quantity?: number
  minQuantity?: number
}

export function DemoForm({ open, initial, onClose, onSaved }:
  { open: boolean; initial: Initial | null; onClose: () => void; onSaved: (input: Initial) => void }) {
  const [name, setName] = useState(initial?.name ?? '')
  const [category, setCategory] = useState(initial?.category ?? '')
  const [sku, setSku] = useState(initial?.sku ?? '')
  const [quantity, setQuantity] = useState(initial?.quantity ?? 0)
  const [minQuantity, setMinQuantity] = useState(initial?.minQuantity ?? 5)

  useEffect(() => {
    if (open) {
      setName(initial?.name ?? '')
      setCategory(initial?.category ?? '')
      setSku(initial?.sku ?? '')
      setQuantity(initial?.quantity ?? 0)
      setMinQuantity(initial?.minQuantity ?? 5)
    }
  }, [open, initial])

  function submit() {
    const errs: typeof errors = {}
    const trimmed = name.trim()
    if (trimmed.length < 1 || trimmed.length > 80) errs.name = 'name is required (1-80 chars)'
    const trimmedCat = category.trim()
    if (trimmedCat.length < 1 || trimmedCat.length > 40) errs.category = 'category is required (1-40 chars)'
    const trimmedSku = sku.trim()
    if (trimmedSku.length < 1 || trimmedSku.length > 40) errs.sku = 'sku is required (1-40 chars)'
    const trimmedQ = quantity.toString().trim()
    if (!trimmedQ.match(/^-?\d+$/)) errs.quantity = 'quantity must be an integer 0-1000000'
    const trimmedMq = minQuantity.toString().trim()
    if (!trimmedMq.match(/^-?\d+$/)) errs.minQuantity = 'minQuantity must be an integer 0-1000000'
    setErrors(errs)
    if (Object.keys(errs).length > 0) return
    onSaved({ name: trimmed, category: trimmedCat, sku: trimmedSku, quantity: trimmedQ, minQuantity: trimmedMq })
  }

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{initial?.id ? 'Edit entry' : 'New entry'}</DialogTitle>
        </DialogHeader>
        <div className="grid gap-4">
          <div className="grid gap-2">
            <Label htmlFor="demo-name">Name</Label>
            <Input id="demo-name" value={name} onChange={(e) => setName(e.target.value)} />
            {errors.name && <p className="text-xs text-destructive">{errors.name}</p>}
          </div>
          <div className="grid gap-2">
            <Label htmlFor="demo-category">Category</Label>
            <Input id="demo-category" value={category} onChange={(e) => setCategory(e.target.value)} />
            {errors.category && <p className="text-xs text-destructive">{errors.category}</p>}
          </div>
          <div className="grid gap-2">
            <Label htmlFor="demo-sku">SKU</Label>
            <Input id="demo-sku" value={sku} onChange={(e) => setSku(e.target.value)} />
            {errors.sku && <p className="text-xs text-destructive">{errors.sku}</p>}
          </div>
          <div className="grid gap-2">
            <Label htmlFor="demo-quantity">Quantity</Label>
            <Input id="demo-quantity" value={quantity} onChange={(e) => setQuantity(e.target.value)} />
            {errors.quantity && <p className="text-xs text-destructive">{errors.quantity}</p>}
          </div>
          <div className="grid gap-2">
            <Label htmlFor="demo-min-quantity">Min quantity</Label>
            <Input id="demo-min-quantity" value={minQuantity} onChange={(e) => setMinQuantity(e.target.value)} />
            {errors.minQuantity && <p className="text-xs text-destructive">{errors.minQuantity}</p>}
          </div>
        </div>
